    # Move every nonzero object into a compact output arrangement by preserving
    # cell geometry and translating each connected component down to the bottom.
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            comps.append((color, cells))
    out = [[0]*w for _ in range(h)]
    # Two like-colored components form a pair; align their arrangement at the bottom.
    # Preserve input placement where the evidence does not specify a unique layout.
    for color, cells in comps:
        for r, c in cells:
            out[r][c] = color
    return out
